using System.Reflection;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Text.Json.Serialization;
using System.Xml.Linq;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Routing;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Options;

namespace PubSoft.Edge;

/// <summary>
/// Edge OpenAPI options — the gateway is a single method-dispatch endpoint, so
/// Swashbuckle-style scanners cannot see handlers. This doc is generated by reflecting
/// the registered <see cref="IEdgeHandler"/> set instead.
///
/// The document endpoint exposes the full method catalog and parameter schemas —
/// treat it as a protected/dev surface (gate by environment or network), it is opt-in.
/// </summary>
public sealed class EdgeOpenApiOptions
{
    public const string SectionName = "Edge:OpenApi";

    /// <summary>Path of the OpenAPI JSON document.</summary>
    public string DocumentPath { get; set; } = "/openapi.json";

    /// <summary>Path of the Swagger UI page.</summary>
    public string UiPath { get; set; } = "/docs";

    /// <summary>Whether to serve the Swagger UI page (loads assets from <see cref="SwaggerUiCssUrl"/>/<see cref="SwaggerUiBundleUrl"/>).</summary>
    public bool UiEnabled { get; set; } = true;

    /// <summary>Document title.</summary>
    public string Title { get; set; } = "Edge RPC";

    /// <summary>Document version.</summary>
    public string Version { get; set; } = "1.0.0";

    /// <summary>Document description.</summary>
    public string? Description { get; set; }

    /// <summary>clientId example shown in the envelope schema (e.g. "demo-app").</summary>
    public string? ClientIdExample { get; set; }

    /// <summary>Swagger UI stylesheet URL.</summary>
    public string SwaggerUiCssUrl { get; set; } = "https://unpkg.com/swagger-ui-dist@5/swagger-ui.css";

    /// <summary>Swagger UI bundle URL.</summary>
    public string SwaggerUiBundleUrl { get; set; } = "https://unpkg.com/swagger-ui-dist@5/swagger-ui-bundle.js";
}

/// <summary>
/// Edge OpenAPI document builder — OpenAPI 3.0.3 generated from the registered
/// <see cref="IEdgeHandler"/> set:
/// <list type="bullet">
/// <item><c>POST {gatewayPath}</c> — the real endpoint (<see cref="EdgeRpcRequest"/> envelope schema)</item>
/// <item><c>POST {gatewayPath}/{method}</c> — one pseudo-path per method, emitted only when
/// <see cref="EdgeGatewayOptions.EnablePseudoPaths"/> is on (Try-it-out compatible)</item>
/// <item><c>x-edge-methods</c> — machine-readable method catalog (method, schemes, params $ref)</item>
/// </list>
/// XML doc comments (<c>&lt;summary&gt;</c>) on handler classes and params properties become
/// descriptions when the consuming project emits .xml documentation files
/// (<c>GenerateDocumentationFile</c>, on by default for PubSoft projects).
/// </summary>
public static class EdgeOpenApiDocument
{
    /// <summary>Builds the OpenAPI document for the given handler set.</summary>
    public static JsonObject Build(
        IEnumerable<IEdgeHandler> handlers,
        string gatewayPath,
        EdgeOpenApiOptions? options = null,
        EdgeGatewayOptions? gatewayOptions = null)
        => new Builder(options ?? new EdgeOpenApiOptions(), gatewayOptions ?? new EdgeGatewayOptions(),
            gatewayPath.TrimEnd('/')).Build(handlers);

    private sealed class Builder(EdgeOpenApiOptions opts, EdgeGatewayOptions gwOpts, string gatewayPath)
    {
        private static readonly JsonNamingPolicy Camel = JsonNamingPolicy.CamelCase;

        private readonly JsonObject _schemas = new();
        private readonly Dictionary<Type, string> _schemaIds = new();
        private readonly HashSet<string> _usedIds = new(StringComparer.Ordinal);
        private readonly Dictionary<Assembly, Dictionary<string, XElement>> _xmlCache = new();

        public JsonObject Build(IEnumerable<IEdgeHandler> handlers)
        {
            var methods = new JsonArray();
            var paths = new JsonObject();
            var pseudoPaths = gwOpts.EnablePseudoPaths;

            RegisterSchema(typeof(EdgeRpcRequest), "EdgeRpcRequest");
            RegisterSchema(typeof(EdgeRpcResponse), "EdgeRpcResponse");
            AdjustEnvelopeSchema();
            var envelope = new JsonObject { ["$ref"] = "#/components/schemas/EdgeRpcRequest" };
            var response = new JsonObject { ["$ref"] = "#/components/schemas/EdgeRpcResponse" };

            var ordered = handlers.OrderBy(h => h.Method, StringComparer.Ordinal).ToList();
            foreach (var handler in ordered)
            {
                var handlerType = handler.GetType();
                var method = handler.Method;
                var schemes = SchemesOf(handler);
                var summary = XmlSummary("T:" + handlerType.FullName, handlerType.Assembly);

                var paramsType = ParamsTypeOf(handlerType);
                var paramSchema = paramsType is null
                    ? new JsonObject { ["type"] = "object" }
                    : ParamsSchemaFor(paramsType);

                var entry = new JsonObject
                {
                    ["method"] = method,
                    ["schemes"] = new JsonArray(schemes.Select(s => (JsonNode)Camel.ConvertName(s.ToString())).ToArray()),
                    ["params"] = paramSchema.DeepClone(),
                };
                if (summary is not null)
                    entry["description"] = summary;
                methods.Add(entry);

                if (pseudoPaths)
                    paths[$"{gatewayPath}/{method}"] = PseudoPath(method, schemes, summary, paramSchema);
            }

            paths[gatewayPath] = GatewayPath(envelope, response);
            if (ordered.Count > 0)
            {
                var first = ordered[0];
                var firstParams = ParamsTypeOf(first.GetType()) is { } t
                    ? ParamsSchemaFor(t)
                    : new JsonObject { ["type"] = "object" };
                ((JsonObject)paths[gatewayPath]!["post"]!["requestBody"]!["content"]!["application/json"]!)
                    ["example"] = EnvelopeExample(first.Method, PreferredScheme(SchemesOf(first)), firstParams);
            }

            return new JsonObject
            {
                ["openapi"] = "3.0.3",
                ["info"] = new JsonObject
                {
                    ["title"] = opts.Title,
                    ["version"] = opts.Version,
                    ["description"] = opts.Description
                        ?? $"Edge RPC gateway — every method is POST {gatewayPath} with envelope.method dispatch.",
                },
                ["paths"] = paths,
                ["components"] = new JsonObject
                {
                    ["schemas"] = _schemas,
                    ["securitySchemes"] = new JsonObject
                    {
                        ["edgeSession"] = new JsonObject
                        {
                            ["type"] = "apiKey", ["in"] = "body", ["name"] = "credential",
                            ["description"] = "scheme=session — credential carries the sessionKey issued by a login method",
                        },
                        ["edgeSignature"] = new JsonObject
                        {
                            ["type"] = "apiKey", ["in"] = "body", ["name"] = "credential",
                            ["description"] = "scheme=hmac/md5 — credential carries the canonical-string signature over method/timestamp/nonce/params",
                        },
                    },
                },
                ["x-edge-methods"] = methods,
            };
        }

        // ── path builders ──

        private JsonObject GatewayPath(JsonObject envelope, JsonObject response)
        {
            var pseudoNote = gwOpts.EnablePseudoPaths
                ? $" Pseudo-paths {gatewayPath}/{{method}} are accepted and listed per method."
                : "";
            return new JsonObject
            {
                ["post"] = new JsonObject
                {
                    ["summary"] = "Edge RPC gateway",
                    ["description"] = $"All methods share this endpoint; envelope.method selects the handler.{pseudoNote} Method catalog: x-edge-methods.",
                    ["requestBody"] = new JsonObject
                    {
                        ["required"] = true,
                        ["content"] = new JsonObject
                        {
                            ["application/json"] = new JsonObject { ["schema"] = envelope },
                        },
                    },
                    ["responses"] = new JsonObject
                    {
                        ["200"] = new JsonObject
                        {
                            ["description"] = "Uniform envelope response — the code lives in the body (HTTP is always 200).",
                            ["content"] = new JsonObject
                            {
                                ["application/json"] = new JsonObject { ["schema"] = response },
                            },
                        },
                    },
                },
            };
        }

        private JsonObject PseudoPath(string method, EdgeAuthScheme[] schemes, string? summary, JsonObject paramSchema)
        {
            var schemeNames = string.Join("|", schemes.Select(s => Camel.ConvertName(s.ToString())));
            var media = new JsonObject { ["schema"] = PseudoRequestSchema(paramSchema, schemes) };

            // One ready-to-send example per accepted scheme — Swagger UI shows them as a
            // dropdown in Try-it-out; `none` bodies execute unmodified.
            var examples = new JsonObject();
            foreach (var scheme in schemes.OrderBy(TryOrder))
            {
                examples[Camel.ConvertName(scheme.ToString())] = new JsonObject
                {
                    ["summary"] = SchemeHint(scheme),
                    ["value"] = EnvelopeExample(null, scheme, paramSchema),
                };
            }
            media["examples"] = examples;
            media["example"] = EnvelopeExample(null, PreferredScheme(schemes), paramSchema);

            return new JsonObject
            {
                ["post"] = new JsonObject
                {
                    ["summary"] = FirstLine(summary) ?? method,
                    ["description"] = (summary ?? "") + $"\n\nwire: POST {gatewayPath}, envelope.method=\"{method}\", accepted schemes: {schemeNames}",
                    ["tags"] = new JsonArray(method.Split('.')[0]),
                    ["operationId"] = method.Replace('.', '_').Replace('-', '_'),
                    ["requestBody"] = new JsonObject
                    {
                        ["required"] = true,
                        ["content"] = new JsonObject
                        {
                            ["application/json"] = media,
                        },
                    },
                    ["responses"] = new JsonObject
                    {
                        ["200"] = new JsonObject
                        {
                            ["description"] = "EdgeRpcResponse — data holds the method result",
                            ["content"] = new JsonObject
                            {
                                ["application/json"] = new JsonObject
                                {
                                    ["schema"] = new JsonObject { ["$ref"] = "#/components/schemas/EdgeRpcResponse" },
                                },
                            },
                        },
                    },
                },
            };
        }

        /// <summary>Envelope minus `method` (carried by the pseudo-path), params typed to the method.</summary>
        private JsonObject PseudoRequestSchema(JsonObject paramSchema, EdgeAuthScheme[] schemes)
        {
            var envelopeProps = (JsonObject)((JsonObject)_schemas["EdgeRpcRequest"]!["properties"]!).DeepClone();
            envelopeProps.Remove("method");
            envelopeProps["params"] = paramSchema;
            // Property-level examples — shown in the Schema tab and merged into generated samples.
            ((JsonObject)envelopeProps["clientId"]!)["example"] = opts.ClientIdExample ?? "demo-app";
            ((JsonObject)envelopeProps["scheme"]!)["example"] = Camel.ConvertName(PreferredScheme(schemes).ToString());
            ((JsonObject)envelopeProps["timestamp"]!)["example"] = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
            return new JsonObject
            {
                ["type"] = "object",
                ["required"] = new JsonArray("clientId"),
                ["properties"] = envelopeProps,
            };
        }

        // ── examples ──

        /// <summary>Scheme ordered by try-out convenience: none first, signatures last.</summary>
        private static int TryOrder(EdgeAuthScheme s) => s switch
        {
            EdgeAuthScheme.None => 0,
            EdgeAuthScheme.Session => 1,
            EdgeAuthScheme.Hmac => 2,
            EdgeAuthScheme.Md5 => 3,
            _ => 4,
        };

        private static EdgeAuthScheme PreferredScheme(EdgeAuthScheme[] schemes)
            => schemes.OrderBy(TryOrder).FirstOrDefault();

        private static string SchemeHint(EdgeAuthScheme s) => s switch
        {
            EdgeAuthScheme.None => "scheme=none — send as-is",
            EdgeAuthScheme.Session => "scheme=session — put a sessionKey (from a login method) into credential",
            EdgeAuthScheme.Hmac => "scheme=hmac — credential = canonical HMAC-SHA256 signature",
            EdgeAuthScheme.Md5 => "scheme=md5 — credential = canonical MD5 signature",
            _ => s.ToString(),
        };

        /// <summary>A ready-to-edit request body example; method is null for pseudo-paths (path carries it).</summary>
        private JsonObject EnvelopeExample(string? method, EdgeAuthScheme scheme, JsonObject paramSchema)
        {
            var body = new JsonObject
            {
                ["clientId"] = opts.ClientIdExample ?? "demo-app",
            };
            if (method is not null)
                body["method"] = method;
            body["scheme"] = Camel.ConvertName(scheme.ToString());
            body["credential"] = scheme switch
            {
                EdgeAuthScheme.Session => "<sessionKey>",
                EdgeAuthScheme.Hmac or EdgeAuthScheme.Md5 => "<signature>",
                _ => "",
            };
            body["timestamp"] = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
            body["nonce"] = "docs";
            body["params"] = ExampleForSchema(paramSchema, []);
            return body;
        }

        /// <summary>Stub JSON generated from a schema node ($ref resolved against components.schemas).</summary>
        private JsonNode ExampleForSchema(JsonNode? schema, HashSet<string> visited)
        {
            if (schema is not JsonObject obj)
                return schema?.DeepClone() ?? new JsonObject();
            if (obj["$ref"]?.GetValue<string>() is { } refId)
            {
                var id = refId.Split('/')[^1];
                if (!visited.Add(id) || _schemas[id] is not { } target)
                    return new JsonObject();
                return ExampleForSchema(target, visited);
            }
            if (obj["default"] is { } d)
                return d.DeepClone();
            if (obj["enum"] is JsonArray enums && enums.Count > 0)
                return enums[0]!.DeepClone();
            return obj["type"]?.GetValue<string>() switch
            {
                "object" => ObjectExample(obj, visited),
                "array" => new JsonArray(),
                "string" => "",
                "integer" or "number" => 0,
                "boolean" => false,
                _ => new JsonObject(),
            };
        }

        private JsonObject ObjectExample(JsonObject schema, HashSet<string> visited)
        {
            var result = new JsonObject();
            if (schema["properties"] is JsonObject props)
                foreach (var kv in props)
                    result[kv.Key] = ExampleForSchema(kv.Value, visited);
            return result;
        }

        private void AdjustEnvelopeSchema()
        {
            var envelope = (JsonObject)_schemas["EdgeRpcRequest"]!;
            // The gateway validates clientId + method only; credential/timestamp/nonce are
            // per-scheme (sessionKey for session, signed fields for hmac/md5, unused for none).
            envelope["required"] = new JsonArray("clientId", "method");
            var props = (JsonObject)envelope["properties"]!;
            var cred = (JsonObject)props["credential"]!;
            cred["description"] = AppendNote((string?)cred["description"],
                "session: sessionKey; hmac/md5: signature; none: empty");
            var paramsProp = (JsonObject)props["params"]!;
            paramsProp["description"] = "Method params — shape per method (see x-edge-methods or the per-method pseudo-paths)";
            if (opts.ClientIdExample is { } example)
                ((JsonObject)props["clientId"]!)["example"] = example;
        }

        // ── schema generation ──

        /// <summary>params schema — inline empty object for parameterless params types, else a $ref.</summary>
        private JsonObject ParamsSchemaFor(Type paramsType)
        {
            var props = paramsType.GetProperties(BindingFlags.Public | BindingFlags.Instance)
                .Where(p => p.GetIndexParameters().Length == 0).ToArray();
            if (props.Length == 0)
                return new JsonObject { ["type"] = "object", ["properties"] = new JsonObject() };
            return SchemaRefFor(paramsType);
        }

        private JsonObject SchemaRefFor(Type type)
        {
            var id = RegisterSchema(type, null);
            return new JsonObject { ["$ref"] = $"#/components/schemas/{id}" };
        }

        /// <summary>Registers an object schema under components.schemas; returns the schema id.</summary>
        private string RegisterSchema(Type type, string? preferredId)
        {
            if (_schemaIds.TryGetValue(type, out var existing))
                return existing;

            var id = preferredId ?? SchemaId(type);
            _schemaIds[type] = id;
            _schemas[id] = new JsonObject(); // placeholder — recursive references resolve to this id
            _schemas[id] = BuildObjectSchema(type);
            return id;
        }

        private string SchemaId(Type type)
        {
            var id = type.Name;
            if (_usedIds.Add(id))
                return id;
            // Name collision across namespaces — disambiguate with the full name.
            id = type.FullName!.Replace('+', '_').Replace('.', '_');
            _usedIds.Add(id);
            return id;
        }

        private JsonObject BuildObjectSchema(Type type)
        {
            var props = new JsonObject();
            var required = new JsonArray();
            var nullCtx = new NullabilityInfoContext();

            foreach (var p in type.GetProperties(BindingFlags.Public | BindingFlags.Instance))
            {
                if (p.GetIndexParameters().Length != 0)
                    continue;
                if (p.GetCustomAttribute<JsonIgnoreAttribute>() is { Condition: JsonIgnoreCondition.Always })
                    continue;

                var name = p.GetCustomAttribute<JsonPropertyNameAttribute>()?.Name
                    ?? Camel.ConvertName(p.Name);
                var propSchema = TypeSchema(p.PropertyType);
                var doc = XmlSummary($"P:{p.DeclaringType!.FullName}.{p.Name}", p.DeclaringType!.Assembly);
                if (doc is not null)
                    propSchema["description"] = FirstLine(doc);
                props[name] = propSchema;

                var requiredAttr = p.GetCustomAttribute<JsonRequiredAttribute>() is not null;
                var nullable = Nullable.GetUnderlyingType(p.PropertyType) is not null
                    || nullCtx.Create(p).ReadState == NullabilityState.Nullable;
                if (requiredAttr || !nullable)
                    required.Add(name);
            }

            var schema = new JsonObject { ["type"] = "object", ["properties"] = props };
            if (required.Count > 0)
                schema["required"] = required;
            var typeDoc = XmlSummary("T:" + type.FullName, type.Assembly);
            if (typeDoc is not null)
                schema["description"] = typeDoc;
            return schema;
        }

        private JsonObject TypeSchema(Type t)
        {
            if (Nullable.GetUnderlyingType(t) is { } underlying)
                return TypeSchema(underlying);
            if (t == typeof(object) || t == typeof(JsonElement) || t == typeof(JsonElement?))
                return new JsonObject(); // unconstrained — honest "any JSON"
            if (t == typeof(string))
                return new JsonObject { ["type"] = "string" };
            if (t == typeof(bool))
                return new JsonObject { ["type"] = "boolean" };
            if (t == typeof(long) || t == typeof(ulong))
                return new JsonObject { ["type"] = "integer", ["format"] = "int64" };
            if (t == typeof(int) || t == typeof(uint) || t == typeof(short) || t == typeof(ushort)
                || t == typeof(byte) || t == typeof(sbyte) || t == typeof(char))
                return new JsonObject { ["type"] = "integer", ["format"] = "int32" };
            if (t == typeof(decimal) || t == typeof(double) || t == typeof(float))
                return new JsonObject { ["type"] = "number" };
            if (t == typeof(Guid))
                return new JsonObject { ["type"] = "string", ["format"] = "uuid" };
            if (t == typeof(Uri))
                return new JsonObject { ["type"] = "string", ["format"] = "uri" };
            if (t == typeof(DateTime) || t == typeof(DateTimeOffset))
                return new JsonObject { ["type"] = "string", ["format"] = "date-time" };
            if (t == typeof(DateOnly))
                return new JsonObject { ["type"] = "string", ["format"] = "date" };
            if (t == typeof(TimeOnly))
                return new JsonObject { ["type"] = "string", ["format"] = "time" };
            if (t == typeof(byte[]))
                return new JsonObject { ["type"] = "string", ["format"] = "byte" };
            if (t.IsEnum)
                // Wire enums are camelCase strings (EdgeJsonOptions uses JsonStringEnumConverter).
                return new JsonObject
                {
                    ["type"] = "string",
                    ["enum"] = new JsonArray(Enum.GetNames(t).Select(n => (JsonNode)Camel.ConvertName(n)).ToArray()),
                };
            if (DictionaryValueType(t) is { } valueType)
                return new JsonObject { ["type"] = "object", ["additionalProperties"] = TypeSchema(valueType) };
            if (ElementType(t) is { } elem)
                return new JsonObject { ["type"] = "array", ["items"] = TypeSchema(elem) };
            return SchemaRefFor(t);
        }

        private static Type? ElementType(Type t)
        {
            if (t == typeof(string))
                return null;
            if (t.IsArray)
                return t.GetElementType();
            return t.GetInterfaces().Concat([t])
                .FirstOrDefault(i => i.IsGenericType && i.GetGenericTypeDefinition() == typeof(IEnumerable<>))
                ?.GetGenericArguments()[0];
        }

        private static Type? DictionaryValueType(Type t)
        {
            var dict = t.GetInterfaces().Concat([t])
                .FirstOrDefault(i => i.IsGenericType && i.GetGenericTypeDefinition() == typeof(IDictionary<,>));
            return dict is not null && dict.GetGenericArguments()[0] == typeof(string)
                ? dict.GetGenericArguments()[1]
                : null;
        }

        // ── handler metadata ──

        /// <summary>Same precedence as the gateway: attribute wins over the interface property.</summary>
        private static EdgeAuthScheme[] SchemesOf(IEdgeHandler handler)
            => handler.GetType().GetCustomAttribute<EdgeSchemeAttribute>()?.Schemes ?? handler.Schemes;

        /// <summary>TParams of EdgeHandlerBase&lt;TParams&gt; — walks the whole base chain.</summary>
        private static Type? ParamsTypeOf(Type handlerType)
        {
            for (var t = handlerType; t is not null; t = t.BaseType)
            {
                if (t.IsGenericType && t.GetGenericTypeDefinition() == typeof(EdgeHandlerBase<>))
                    return t.GetGenericArguments()[0];
            }
            return null;
        }

        // ── XML doc comments ──

        private Dictionary<string, XElement> XmlDocs(Assembly assembly)
        {
            if (_xmlCache.TryGetValue(assembly, out var cached))
                return cached;
            var docs = new Dictionary<string, XElement>();
            try
            {
                var xmlPath = assembly.Location is { Length: > 0 } loc ? Path.ChangeExtension(loc, ".xml") : null;
                if (xmlPath is not null && File.Exists(xmlPath))
                    docs = XDocument.Load(xmlPath).Descendants("member")
                        .Where(m => m.Attribute("name") is not null)
                        .ToDictionary(m => m.Attribute("name")!.Value, m => m);
            }
            catch
            {
                // Missing/corrupt doc file — descriptions are optional.
            }
            _xmlCache[assembly] = docs;
            return docs;
        }

        private string? XmlSummary(string memberName, Assembly assembly)
        {
            if (!XmlDocs(assembly).TryGetValue(memberName, out var member))
                return null;
            var summary = member.Element("summary")?.Value.Trim();
            return string.IsNullOrWhiteSpace(summary) ? null : summary;
        }

        private static string? FirstLine(string? s) => s?.Split('\n')[0].Trim();

        private static string AppendNote(string? existing, string note)
            => string.IsNullOrWhiteSpace(existing) ? note : existing + " — " + note;
    }
}

/// <summary>
/// DI and endpoint extensions for the Edge OpenAPI surface.
/// </summary>
public static class EdgeOpenApiExtensions
{
    /// <summary>Configures the OpenAPI document surface.</summary>
    public static IServiceCollection AddEdgeOpenApi(this IServiceCollection services, Action<EdgeOpenApiOptions> configure)
    {
        services.Configure(configure);
        return services;
    }

    /// <summary>Binds OpenAPI options from configuration (Edge:OpenApi).</summary>
    public static IServiceCollection AddEdgeOpenApi(this IServiceCollection services, IConfiguration configuration)
    {
        services.Configure<EdgeOpenApiOptions>(configuration.GetSection(EdgeOpenApiOptions.SectionName));
        return services;
    }

    /// <summary>
    /// Maps the OpenAPI document (<see cref="EdgeOpenApiOptions.DocumentPath"/>) and, when
    /// <see cref="EdgeOpenApiOptions.UiEnabled"/>, the Swagger UI page (<see cref="EdgeOpenApiOptions.UiPath"/>).
    /// The document reflects the handlers registered in DI at first request.
    /// <code>
    /// app.MapEdgeOpenApi("/rpc");
    /// </code>
    /// </summary>
    public static IEndpointRouteBuilder MapEdgeOpenApi(this IEndpointRouteBuilder endpoints, string gatewayPath = "/rpc")
    {
        var opts = endpoints.ServiceProvider.GetService<IOptions<EdgeOpenApiOptions>>()?.Value
            ?? new EdgeOpenApiOptions();
        var gwOpts = endpoints.ServiceProvider.GetService<IOptions<EdgeGatewayOptions>>()?.Value
            ?? new EdgeGatewayOptions();
        var path = gatewayPath.TrimEnd('/');

        var document = new Lazy<string>(() => EdgeOpenApiDocument
            .Build(endpoints.ServiceProvider.GetServices<IEdgeHandler>(), path, opts, gwOpts)
            .ToJsonString());

        endpoints.MapGet(opts.DocumentPath, () => Results.Content(document.Value, "application/json"));

        if (opts.UiEnabled)
        {
            var html = SwaggerUiHtml(opts);
            endpoints.MapGet(opts.UiPath, () => Results.Content(html, "text/html"));
        }

        return endpoints;
    }

    private static string SwaggerUiHtml(EdgeOpenApiOptions opts)
    {
        var title = System.Net.WebUtility.HtmlEncode(opts.Title);
        var css = System.Net.WebUtility.HtmlEncode(opts.SwaggerUiCssUrl);
        var js = System.Net.WebUtility.HtmlEncode(opts.SwaggerUiBundleUrl);
        var docUrl = JsonSerializer.Serialize(opts.DocumentPath);
        return $$"""
            <!DOCTYPE html><html><head><meta charset="utf-8"><title>{{title}}</title>
            <link rel="stylesheet" href="{{css}}"></head>
            <body><div id="ui"></div>
            <script src="{{js}}"></script>
            <script>SwaggerUIBundle({url:{{docUrl}},dom_id:"#ui",tryItOutEnabled:true,displayRequestDuration:true});</script>
            </body></html>
            """;
    }
}
